def replace_emojis(content):
    for emoji, svg in svg_map.items():
        # Handle string literals in script (e.g. icon: '🏠')
        content = content.replace(f"icon: '{emoji}'", f"icon: '{svg}'")
        # Handle inline emojis in Vue template
        # The syntax <span v-html="'...'"></span> works if we just insert the raw SVG
        # Actually since the SVG is an HTML string, if we are inside a template tag we can just put the SVG directly
        # E.g. <div class="...">🏠</div> -> <div class="..."> <svg...> </div>
        content = content.replace(emoji, svg)
    return content

directory = 'src/components'
for filename in os.listdir(directory):
    if filename.endswith('.vue'):
        filepath = os.path.join(directory, filename)
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
        
        # specific Vue rendering fixes
        content = content.replace('<span class="navbar__mobile-icon">{{ link.icon }}</span>', '<span class="navbar__mobile-icon" v-html="link.icon"></span>')
        content = content.replace('<span class="navbar__dropdown-icon">{{ child.icon }}</span>', '<span class="navbar__dropdown-icon" v-html="child.icon"></span>')
        
        # specific logo replacement Navbar
        logo_svg_pattern = re.compile(r'<svg.*?id="logoGrad".*?</svg>', re.DOTALL)
        content = logo_svg_pattern.sub(r'<img src="/images/Logo_2-01.png" alt="Red Sea HVAC Services" style="height: 50px; width: auto;" />', content)
        
        # specific logo replacement Footer
        footer_logo_svg_pattern = re.compile(r'<svg.*?id="footerLogoGrad".*?</svg>', re.DOTALL)
        content = footer_logo_svg_pattern.sub(r'<img src="/images/Logo_2-01.png" alt="Red Sea HVAC Services" style="height: 50px; width: auto;" />', content)
        
        new_content = replace_emojis(content)
        
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(new_content)

print("Replaced emojis in Vue components.")
